{{#when::{{getvar::astarot-asset}}::is::1}}
{{#when::{{? {{getvar::astarot-infdist}} == 1}}::or::{{? {{chat_index}} > {{? {{lastmessageid}}-10}}}}}}
<div class="astarot-img-root">
  <div class="astarot-img-clip">
    <img alt="" class="astarot-img" src="{{raw::astarot-$<emotion>.png}}" />
  </div>
</div>
{{/when}}
<style>
  .astarot-img-root {
    --py: 11px;
    aspect-ratio: 1/1;
    width: 320px;
    box-sizing: border-box;
    clear: both;
    {{#when::{{getvar::astarot-align}}::is::1}}
    margin: 1.25em auto;
    {{:else}}
    margin: 1.25em 0;
    {{/when}}
    overflow: hidden;
    padding: var(--py) 0;
    position: relative;
    transition: 350ms cubic-bezier(0.5, 0.1, 0.2, 1);
  }

  .astarot-img-root::before {
    border: 10px solid;
    border-image: url({{raw::astarot-border.png}}) stretch;
    border-image-outset: var(--py) 0;
    border-image-slice: 119 90;
    border-image-width: 59.5px 45px;
    content: '';
    height: calc(100% - var(--py) * 2);
    inset: 0;
    pointer-events: none;
    position: absolute;
    top: var(--py);
    transition: 350ms cubic-bezier(0.5, 0.1, 0.2, 1);
    width: 100%;
  }

{{#when::{{getvar::astarot-hover}}::is::1}}
  .astarot-img-root:hover {
    aspect-ratio: 1/1.4;
  }
{{/when}}
  .astarot-img-root:hover::before {
    opacity: 0;
  }

  .astarot-img-clip {
    border-radius: 18px;
    height: 100%;
    overflow: hidden;
    width: 100%;
  }

  .astarot-img {
    display: block;
    margin: 0;
    object-fit: cover;
    object-position: top center;
    width: 100%;
  }
</style>
{{/when}}

{{#when::{{getvar::astarot-asset}}::is::1}}
{{#when {{? {{length::$<major>}} > 0}}}}
<img alt class="astarot-desc-card astarot-card"{{#when {{? {{length::$<reversed>}} > 0}}}} data-reversed{{/when}} src="{{raw::astarot-$<major>}}">
{{/when}}
{{#when {{? {{length::$<suit>}} > 0}}}}
<img alt class="astarot-desc-card astarot-card"{{#when {{? {{length::$<reversed>}} > 0}}}} data-reversed{{/when}} src="{{raw::astarot-suit-$<suit>}}" data-num="$<num>">
{{/when}}
{{/when}}

{{#when::{{? {{chat_index}} > {{? {{lastmessageid}}-5}}}}}}
<details class="astarot-panel" open>
  <summary class="astarot-summary">
    {{#when::{{chat_index}}::is::-1}}
      <img class="astarot-cover" src="{{raw::$1}}" />
      <div class="astarot-title-overlay">
        /설정 or /config ▼
      </div>
    {{:else}}
      <div class="astarot-title-overlay">
        /설정 or /config ▼
      </div>
    {{/when}}
  </summary>
  <div class="astarot-content-wrapper">
    <div class="astarot-controls-section">
      <div>
        <div class="astarot-label">Language</div>
        <div class="astarot-lang-group">
          <button class="astarot-btn" {{#when::{{getvar::astarot-lang}}::is::0}}data-active{{/when}} {{#when::not::{{getvar::lang}}::is::0}}risu-trigger="toggleLang"{{/when}}>한국어</button>
          <button class="astarot-btn" {{#when::{{getvar::astarot-lang}}::is::1}}data-active{{/when}} {{#when::not::{{getvar::lang}}::is::1}}risu-trigger="toggleLang"{{/when}}>English</button>
        </div>
      </div>
      <div class="astarot-misc-groups">
        <div>
          <div class="astarot-label">Contents</div>
          <div class="astarot-misc-group">
            <button class="astarot-btn" {{#when::{{getvar::astarot-reading}}::is::1}}data-active{{/when}} risu-trigger="toggleReading">타로 리딩</button>
            <button class="astarot-btn" {{#when::{{getvar::astarot-cards}}::is::1}}data-active{{/when}} risu-trigger="toggleCards">카드 외형 로어북</button>
            <button class="astarot-btn" {{#when::{{getvar::astarot-stats}}::is::1}}data-active{{/when}} risu-trigger="toggleStats">상태창</button>
            <button class="astarot-btn" {{#when::{{getvar::astarot-realtime}}::is::1}}data-active{{/when}} risu-trigger="toggleRealTime">현실 날짜/시간 전송</button>
          </div>
        </div>
        <div>
          <div class="astarot-label">Images</div>
          <div class="astarot-misc-group">
            <button class="astarot-btn" {{#when::{{getvar::astarot-asset}}::is::1}}data-active{{/when}} risu-trigger="toggleImage">이미지 표시</button>
            <button class="astarot-btn" {{#when::{{getvar::astarot-hover}}::is::1}}data-active{{/when}} {{#when::{{getvar::astarot-asset}}::is::0}}disabled{{/when}} risu-trigger="toggleHover">호버 확대</button>
            <button class="astarot-btn" {{#when::{{getvar::astarot-infdist}}::is::1}}data-active{{/when}} {{#when::{{getvar::astarot-asset}}::is::0}}disabled{{/when}} risu-trigger="toggleInfdist">무제한 렌더링</button>
            <button class="astarot-btn" {{#when::{{getvar::astarot-align}}::is::1}}data-active{{/when}} {{#when::{{getvar::astarot-asset}}::is::0}}disabled{{/when}} risu-trigger="toggleAlign">중앙 정렬</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</details>
{{#when {{greater::{{chat_index}}::-1}}}}
<button class="astarot-button" risu-trigger="closeConf" style="margin-top:8px">
  설정 닫기
</button>
{{/when}}
{{/when}}

<style>
  .astarot-panel {
    --primary-gold: #cbb69b;
    --text-color: #f0e6d2;
    --panel-bg: #1a1625;
    --btn-text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.8);

    background: var(--panel-bg);
