    background: #000;
    cursor: pointer;
    padding: 0;
    list-style: none;
    margin: 0;
    position: relative;
    width: 100%;
    overflow: hidden;
  }

  .astarot-cover {
    aspect-ratio: 3/2;
    background: #000;
    display: block;
    object-fit: contain;
    object-position: center;
    transition: transform 0.3s ease;
    width: 100%;
  }

  .astarot-title-overlay {
    align-items: flex-end;
    width: 100%;
    background: linear-gradient(to top, rgba(15, 12, 21, 0.95), transparent);
    display: flex;
    justify-content: center;
    color: var(--primary-gold);
    font-weight: 700;
    font-size: 1.2rem;
    letter-spacing: 3px;
    padding: 20px 0;
    text-shadow: 0 2px 4px rgba(0,0,0,0.8);
    z-index: 3;
  }
  .astarot-cover + .astarot-title-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
  }

  .astarot-content-wrapper {
      display: flex;
      flex-direction: column;
      gap: 10px;
      padding: 10px;
      position: relative;
  }

  .astarot-content-wrapper::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: linear-gradient(90deg, transparent, var(--primary-gold), transparent);
    opacity: 0.7;
  }

  .astarot-controls-section {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .astarot-label {
    font-size: 0.8rem;
    color: #8a8199;
    text-align: center;
    margin-bottom: 4px;
    letter-spacing: 1px;
    text-transform: uppercase;
  }

  .astarot-btn {
    background: transparent;
    color: #7e786d;
    font-weight: 700;
    font-size: 0.8rem;
    padding: 8px 24px;
    cursor: pointer;
    text-shadow: var(--btn-text-shadow);
    transition: transform 0.1s;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    user-select: none;
  }

  .astarot-btn::before {
    content: '✦';
    margin-right: 1ch;
    opacity: 0;
  }
  .astarot-btn::after {
    content: '✦';
    color: #7e786d;
    font-size: 0.8rem;
    margin-left: 1ch;
    opacity: 0.6;
  }

  .astarot-btn:not(:disabled):hover {
    filter: brightness(1.2);
    color: #fff;
  }

  .astarot-btn[data-active] {
    color: var(--primary-gold);
    filter: drop-shadow(0 0 5px rgba(212, 175, 55, 0.3));
  }
  .astarot-btn[data-active]:not(:disabled)::after {
    color: var(--primary-gold);
    opacity: 1;
  }

  .astarot-btn:disabled {
    cursor: not-allowed;
    filter: grayscale(1) opacity(0.4);
    color: #555;
  }

  .astarot-lang-group {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .astarot-misc-groups {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }

  .astarot-misc-group {
    display: grid;
    grid-template-columns: 1fr;
    gap: 8px;
  }

  @media (max-width: 600px) {
    .astarot-misc-groups {
      grid-template-columns: 1fr;
    }
  }
</style>

