<style>
.astarot-status-container {
  --primary-gold: #cbb69b;
  --primary-gold-dim: #8a7b66;
  --text-color: #f0e6d2;
  --panel-bg: #1a1625;
  --panel-bg-lighter: #252033;
  --border-color: #3a324b;
  --accent-glow: rgba(203, 182, 155, 0.15);

  background: var(--panel-bg);
  border-radius: 12px;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.7), 0 0 0 1px var(--border-color) inset;
  width: 100%;
  margin: auto;
  max-width: 600px;
  padding: 24px;
  position: relative;
  overflow: hidden;
  font-family: 'Cinzel', serif;
  color: var(--text-color);
}

.astarot-status-container::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--primary-gold), transparent);
  opacity: 0.7;
}

.astarot-status-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

.astarot-status-row {
  display: flex;
  gap: 16px;
}

.astarot-status-item {
  background: rgba(0, 0, 0, 0.2);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  position: relative;
  overflow: hidden;
}

.astarot-status-item::after {
  content: '';
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(to bottom, transparent, var(--primary-gold-dim), transparent);
  opacity: 0.3;
}

.astarot-status-icon-wrapper {
  color: var(--primary-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  filter: drop-shadow(0 0 5px rgba(203, 182, 155, 0.4));
}

.astarot-status-icon-wrapper svg {
  width: 20px;
  height: 20px;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}

.astarot-status-content {
  display: flex;
  flex-direction: column;
  width: 100%;
}

.astarot-status-label {
  font-size: 0.7rem;
  color: #8a8199;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 2px;
}

.astarot-status-value {
  font-size: 0.95rem;
  color: var(--text-color);
  font-weight: 500;
  letter-spacing: 0.5px;
  text-transform: capitalize;
}
</style>
{{/when}}
